function normalizePhone(raw) {
  const digits = String(raw || '').replace(/\D/g, '');
  if (digits.length < 7 || digits.length > 15) return null;
  return '+' + digits;
}

// create_booking — Validate Input
// Expected body: { business_id, customer_name, phone, email, service or
//   service_or_staff, selected_slot, call_id }
// selected_slot is either the whole slot object returned by
// get_available_slots/get_availability ({ start, end, label }) or just an
// ISO start string -- the end is derived from the service duration.
const body = $input.first().json.body || {};

const businessId = String(body.business_id ?? '').trim();
const customerName = String(body.customer_name ?? body.name ?? '').trim();
const rawPhone = String(body.phone ?? body.customer_phone ?? '').trim();
const email = String(body.email ?? body.customer_email ?? '').trim();
const service = String(body.service ?? body.service_or_staff ?? body.service_name ?? '').trim();
const callId = String(body.call_id ?? '').trim() || null;

const rawSlot = body.selected_slot ?? body.slot ?? null;
let slotStartRaw = '';
let slotEndRaw = '';
if (rawSlot && typeof rawSlot === 'object') {
  slotStartRaw = String(rawSlot.start ?? rawSlot.slot_start ?? '').trim();
  slotEndRaw = String(rawSlot.end ?? rawSlot.slot_end ?? '').trim();
} else if (typeof rawSlot === 'string') {
  slotStartRaw = rawSlot.trim();
}
if (!slotStartRaw) slotStartRaw = String(body.slot_start ?? '').trim();
if (!slotEndRaw) slotEndRaw = String(body.slot_end ?? '').trim();

const errors = [];
if (!businessId) errors.push('business_id is required');
if (!customerName) errors.push('customer_name is required');

// Country-agnostic normalization -- see docs/n8n-setup.md "Known
// simplifications". Does not assume a country code; the caller's digits
// must already include one.
const phoneE164 = normalizePhone(rawPhone);
if (!rawPhone) {
  errors.push('phone is required');
} else if (!phoneE164) {
  errors.push('phone must contain 7-15 digits, including country code');
}

if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) {
  errors.push('email is not a valid email address');
}

if (!service) errors.push('service is required');

let slotStart = null;
let slotEnd = null;

if (!slotStartRaw) {
  errors.push('selected_slot is required (an ISO 8601 start time, or { start, end })');
} else {
  slotStart = DateTime.fromISO(slotStartRaw, { setZone: true });
  if (!slotStart.isValid) {
    errors.push('selected_slot start is not a valid ISO 8601 date and time');
  }
}

if (slotEndRaw) {
  slotEnd = DateTime.fromISO(slotEndRaw, { setZone: true });
  if (!slotEnd.isValid) {
    errors.push('selected_slot end is not a valid ISO 8601 date and time');
  } else if (slotStart && slotStart.isValid && slotEnd <= slotStart) {
    errors.push('selected_slot end must be after its start');
  }
}

return [{
  json: {
    valid: errors.length === 0,
    errors,
    business_id_input: businessId,
    customer_name: customerName,
    phone: rawPhone,
    phone_e164: phoneE164,
    email: email || null,
    service,
    call_id: callId,
    slot_start_raw: slotStart && slotStart.isValid ? slotStart.toISO() : null,
    slot_end_raw: slotEnd && slotEnd.isValid ? slotEnd.toISO() : null,
  },
}];

// Normalize Business
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.id ? items[0].json : null;

return [{
  json: {
    business_found: !!row,
    business_id: row ? row.id : null,
    business_timezone: row ? row.timezone : null,
  },
}];

// Normalize Settings
// No settings row is treated as "booking not configured" -- booking_enabled
// defaults false so a business that hasn't been set up yet can never be
// booked into by accident.
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.business_id ? items[0].json : null;

return [{
  json: {
    booking_enabled: row ? !!row.booking_enabled : false,
    availability_source: row ? row.availability_source : 'not_tracked',
    calendar_id: row ? row.calendar_id : null,
  },
}];

// create_booking — Normalize Service
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.id ? items[0].json : null;

return [{
  json: {
    service_found: !!row,
    service_id: row ? row.id : null,
    service_name: row ? row.name : $('Validate Input').first().json.service,
    duration_minutes: row ? row.duration_minutes : null,
    bookable: row ? !!row.bookable : false,
  },
}];

// create_booking — Resolve Slot
// Fills in the slot end from the service duration when the caller only
// sent a start time, and produces the spoken-friendly label reused in the
// response and the calendar event.
const input = $('Validate Input').first().json;
const business = $('Normalize Business').first().json;
const service = $('Normalize Service').first().json;

const tz = business.business_timezone || 'UTC';
const duration = Number(service.duration_minutes);

const start = DateTime.fromISO(input.slot_start_raw, { setZone: true });
const end = input.slot_end_raw
  ? DateTime.fromISO(input.slot_end_raw, { setZone: true })
  : start.plus({ minutes: duration });

return [{
  json: {
    business_timezone: tz,
    slot_start: start.toISO(),
    slot_end: end.toISO(),
    slot_label: start.setZone(tz).toFormat("cccc, LLLL d 'at' h:mm a"),
    duration_minutes: duration,
  },
}];

// create_booking — Normalize Duplicate
// Business-scoped duplicate key: phone + service + slot start, matching a
// non-cancelled appointment for THIS business. Runs before any conflict
// check on purpose: a retried request should find its own prior booking,
// not collide with it.
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.id ? items[0].json : null;

return [{
  json: {
    duplicate_found: !!row,
    existing_booking_id: row ? row.id : null,
    existing_start_time: row ? row.start_time : null,
    existing_end_time: row ? row.end_time : null,
    existing_calendar_event_id: row ? row.calendar_event_id : null,
  },
}];

// create_booking — Normalize Table Conflict
// The appointments table is this project's source of truth regardless of
// whether a business has Google Calendar connected, so this check always
// runs -- catching two callers booking the same business (and, if a
// staff_id is later added to the request, the same staff member) before
// anything is written.
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.id ? items[0].json : null;

return [{ json: { table_conflict: !!row } }];

// create_booking — Check Calendar Conflict
// Re-reads Google Calendar for the exact chosen slot immediately before
// writing. get_availability may have run minutes ago; this closes the
// window where two callers were offered the same slot.
const conflicts = $input
  .all()
  .map((item) => item.json)
  .filter((e) => e && e.id && e.status !== 'cancelled' && e.transparency !== 'transparent');

return [{ json: { conflict: conflicts.length > 0 } }];

// create_booking — Prepare Insert
// Converges the two paths that can reach this point: a business with a
// configured Google Calendar (a fresh event was just created) or one
// without (booking straight into the appointments table). try/catch is
// the standard n8n idiom for "read a node that may not have executed in
// this run" -- referencing a node by name that never ran throws, so this
// treats that as "no calendar event exists" rather than erroring.
let calendarEventId = null;
try {
  const row = $('Create Calendar Event').first().json;
  calendarEventId = row && row.id ? row.id : null;
} catch (e) {
  calendarEventId = null;
}

return [{
  json: {
    calendar_event_id: calendarEventId,
    had_calendar_event: !!calendarEventId,
  },
}];

// create_booking — Verify Saved
// A 2xx from PostgREST with `Prefer: return=representation` should carry
// the inserted row. If there's no row id we do NOT treat the booking as
// confirmed, even though the HTTP call itself didn't error -- the caller
// must never be told they're booked on the strength of an empty response.
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.id ? items[0].json : null;

const slot = $('Resolve Slot').first().json;
const input = $('Validate Input').first().json;
const service = $('Normalize Service').first().json;

return [{
  json: {
    saved: !!row,
    booking_id: row ? row.id : null,
    response_ok: {
      booking_id: row ? row.id : null,
      status: row ? 'confirmed' : 'not_confirmed',
      confirmed: !!row,
      business_id: input.business_id_input,
      service: service.service_name,
      customer_name: input.customer_name,
      customer_phone: input.phone_e164,
      appointment_start: slot.slot_start,
      appointment_end: slot.slot_end,
      appointment_label: slot.slot_label,
      timezone: slot.business_timezone,
      calendar_event_id: row ? row.calendar_event_id : null,
    },
  },
}];

// create_booking — Build Not Confirmed Response
// Reached when a calendar event was created but the Supabase appointment
// row was not. "Rollback Calendar Event" (continueRegularOutput) just ran
// so the slot isn't silently held; a failed rollback still lands here
// rather than swallowing the original failure.
const rollbackItem = $input.first();
const rollbackFailed = !!(rollbackItem && rollbackItem.json && rollbackItem.json.error);

const slot = $('Resolve Slot').first().json;
const service = $('Normalize Service').first().json;
const calendarEventId = $('Prepare Insert').first().json.calendar_event_id;

return [{
  json: {
    error: 'booking_not_saved',
    status: 'not_confirmed',
    confirmed: false,
    booking_id: null,
    message: 'The appointment could not be saved. Do not tell the caller they are booked -- apologise and offer to transfer them.',
    service: service.service_name,
    appointment_start: slot.slot_start,
    appointment_end: slot.slot_end,
    calendar_rollback: rollbackFailed ? 'failed' : 'deleted',
    orphaned_calendar_event_id: rollbackFailed ? calendarEventId : null,
  },
}];
